        Expr j_f = cast<num_t>(j);
        init_x(j) = one + j_f / fn;
    }

    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++)
    //     A[i][j] = (DATA_TYPE)((i + j) % n) / (5*m);
    {
        Expr num  = cast<num_t>((i + j) % n);
        Expr denom = Expr(5 * m);  // promoted to num_t automatically
        init_A(j, i) = num / denom;
    }

    // Simple, cache-friendly schedule for initialization.
    // This runs only once, so we keep it modest.
    Target target = get_host_target();
    const int vec = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Initialize x in parallel, vectorized over j.
    init_x
        .compute_root()
        .vectorize(j, vec)
        .parallel(j, Task::Serial);  // j is 1D; Halide will chunk it for threads

    // Initialize A in tiles to get good locality in both i and j.
    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    init_A
        .compute_root()
        // Tile over j (fast) and i (slow). Small tiles fit nicely in L1.
        .tile(j, i, jo, io, ji, ii, vec, 32)
        .vectorize(ji)
        .parallel(io);

    // Realize into the provided Buffers
    init_x.realize(x);
    init_A.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Vars and reduction domains
    Var i("i"), j("j");

    // Use the runtime extents of A to define the reduction ranges,
    // mirroring the original C loops over N and M.
    RDom r1(0, A.dim(0).extent(), "r1");  // corresponds to j in [0..n-1]
    RDom r2(0, A.dim(1).extent(), "r2");  // corresponds to i in [0..m-1]

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // This is:
    //   tmp[i] = sum_j A[i][j] * x[j];
    //   y[j]   = sum_i A[i][j] * tmp[i];
    //
    // With our layout A(j,i):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(Expr(0));
    y_func(j) += A_param(j, r2) * tmp(r2);

    // -------------------------------------------------------------------------
    // Schedule
    //
    // Goals:
    //  - Good data locality for A and y
    //  - Exploit multicore parallelism
    //  - Use vectorization along contiguous memory in j
    // -------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // ---- Stage 1: tmp(i) = sum_j A(j,i) * x(j) ----
    //
    // For each row i of A, we walk along j (fastest dimension), which is already
    // cache-friendly. We parallelize across i so different rows are processed
    // on different cores. We rely on LLVM to auto-vectorize the reduction over j.
    tmp
        .compute_root()   // materialize full tmp once, like the first C loop nest
        .parallel(i);     // i (rows) are independent

    // ---- Stage 2: y(j) = sum_i A(j,i) * tmp(i) ----
    //
    // Interpretation: for each output j, compute a dot product along i.
    // We want:
    //   - j split into [jo, ji] where ji is vectorized (contiguous over j)
    //   - jo parallelized over threads
    //   - inner loop order: for each (jo, i) process a vector of ji at once
    //
    // This yields:
    //   for jo (parallel)
    //     for i
    //       for ji (vectorized)
    //         y[jo*vec + ji] += A(jo*vec + ji, i) * tmp[i];
    //
    // which accesses A and y contiguously along j/ji.
    Var jo("jo"), ji("ji");

    // Compute y at root, then specialize both the pure (initialization) and
    // update (reduction) stages with the same split of j.
    y_func.compute_root();
    y_func.split(j, jo, ji, vec);

    // Pure definition: y(j) = 0
    // Parallelize over chunks of the output (jo) and vectorize within a chunk.
    y_func
        .reorder(ji, jo)   // inner: ji, outer: jo
        .vectorize(ji)
        .parallel(jo);

    // Update definition: y(j) += A(j, r2) * tmp(r2)
    //
    // Loop order: jo (outer, parallel) -> r2 (over i) -> ji (inner, vector).
    // This keeps j (through ji) as innermost, so we stream A and y contiguously
    // in memory while reducing over i.
    y_func.update()
        .reorder(ji, r2, jo)  // inner: ji, then r2, outer: jo
        .vectorize(ji)
        .parallel(jo);

    // Bind actual Buffers to the ImageParams
    A_param.set(A);
    x_param.set(x);

    // JIT-compile the kernel for this target
    y_func.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run and time the kernel
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize y_func into y buffer
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Print results (to prevent dead-code elimination and for checking)
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print execution time in seconds (like gemm.cpp)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
