    //   for (j = 0; j < n; j++)
    //     A[i][j] = (DATA_TYPE)((i + j) % n) / (5*m);
    {
        Expr num = cast<num_t>((i + j) % n);
        Expr denom = cast<num_t>(Expr(5 * m));  // promoted to num_t
        init_A(j, i) = num / denom;
    }

    // A simple but cache-friendly schedule: parallelize outer dimension,
    // vectorize the fast-varying one.
    Target target = get_host_target();
    const int vec_width =
        std::max(1, target.natural_vector_size(type_of<num_t>()));

    // x(j): 1D contiguous
    init_x.compute_root()
          .vectorize(j, vec_width)
          .parallel(j, 1024);   // coarse-grain parallelism for long vectors

    // A(j,i): j is contiguous, i is slower
    Var io("io"), ji("ji");
    init_A.compute_root()
          .split(j, io, ji, 128)  // tile over j for locality
          .parallel(io)           // parallel over tiles
          .vectorize(ji, vec_width);

    // Realize into the provided Buffers
    init_x.realize(x);
    init_A.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Bind actual Buffers to the ImageParams
    A_param.set(A);
    x_param.set(x);

    // Vars and reduction domains
    Var i("i"), j("j");

    // Use the runtime extents of A to define the reduction ranges,
    // mirroring the original C loops over N and M.
    // r1 corresponds to j in [0..n-1], r2 to i in [0..m-1].
    RDom r1(0, A.dim(0).extent(), "r1");  // over columns j
    RDom r2(0, A.dim(1).extent(), "r2");  // over rows i

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // With our layout A(j,i) (j = column, i = row):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(Expr(0));
    y_func(j) += A_param(j, r2) * tmp(r2);

