    // Schedule for tmp(i) = sum_j A(j,i)*x(j)
    //
    // - Parallelize across i (rows) – independent reductions.
    // - Vectorize across the reduction over j to get dense vector loads
    //   from A(j,i) and x(j), which are contiguous in j.
    // ---------------------------------------
    RVar r1_outer("r1_outer"), r1_inner("r1_inner");

    // Pure definition: tmp(i) = 0
    tmp.compute_root()
       .parallel(i);

    // Reduction step: tmp(i) += ...
    tmp.update()
       .parallel(i)                           // different i can be done in parallel
       .split(r1, r1_outer, r1_inner, vec_width)  // tile reduction over j
       .vectorize(r1_inner);                 // vectorize along contiguous j

