    // Schedule for y(j) = sum_i A(j,i)*tmp(i)
    //
    // We want to:
    //  - Keep j as the innermost loop for good locality on A(j,i) and y(j),
    //  - Parallelize across blocks of j,
    //  - Vectorize within each block of j.
    //
    // The reduction over i (r2) stays serial per j (no cross-j dependence),
    // but we can compute independent j-tiles in parallel.
    // ---------------------------------------
    Var jo("jo"), ji("ji");

    const int y_tile = 64;  // tile size along j; tunable

    // Pure definition: initialize y(j) = 0
    y_func.compute_root()
          .split(j, jo, ji, y_tile)   // tile j
          .parallel(jo)              // parallel over tiles
          .vectorize(ji, vec_width); // vectorize within each tile

    // Reduction step: y(j) += ...
    y_func.update()
          // Make j the innermost loop so that we iterate in memory order
          // over A(j, r2) and y(j).
          .reorder(j, r2)
          // Tile j into [jo, ji] and then reorder so that:
          //   outer: jo (parallel), middle: r2, inner: ji (vectorized j)
          .split(j, jo, ji, y_tile)
          .reorder(ji, r2, jo)
          .parallel(jo)
          .vectorize(ji, vec_width);

